entries[446179] = { ["name"] = "Shoulderplates of Dread", ["text"] = "45 sec cast\nTools: Blacksmith Hammer\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares\nShoulderplates of Dread\nBinds when picked up\nShoulder Plate\n472 Armor\n+12 Strength\n+12 Agility\n+12 Stamina\nDurability 100 / 100\n50\nRequires Blacksmithing\n(250)\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Melee attacks have a chance to increase your attack speed by 5% and attack power by 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446183] = { ["name"] = "Paranoia Mantle", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Chimera Leather (8), Rugged Leather (4)\nParanoia Mantle\nBinds when picked up\nShoulder Leather\n129 Armor\n+16 Agility\n+14 Stamina\nDurability 70 / 70\n50\nRequires Leatherworking\n(250)\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Melee attacks have a chance to increase your attack speed by 5% and attack power by 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446185] = { ["name"] = "Shrieking Spaulders", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Black Dragonscale (8), Rugged Leather (8)\nShrieking Spaulders\nBinds when picked up\nShoulder Mail\n268 Armor\n+17 Agility\n+14 Intellect\nDurability 85 / 85\n50\nRequires Leatherworking\n(250)\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Melee and ranged attacks have a chance to increase your attack power by 60 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446186] = { ["name"] = "Cacophonous Chain Shoulderguards", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Black Dragonscale (4), Rugged Leather (10)\nCacophonous Chain Shoulderguards\nBinds when picked up\nShoulder Mail\n268 Armor\n+12 Strength\n+12 Agility\n+12 Stamina\n+12 Intellect\nDurability 85 / 85\n50\nRequires Leatherworking\n(250)\nEquip: Melee attacks have a chance to increase your attack speed by 5% and attack power by 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446188] = { ["name"] = "Fearmonger's Shoulderguards", ["text"] = "45 sec cast\nTools: Blacksmith Hammer\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares\nFearmonger's Shoulderguards\nBinds when picked up\nShoulder Plate\n472 Armor\n+10 Intellect\nDurability 100 / 100\n50\nRequires Blacksmithing\n(250)\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases damage done by Holy spells and effects by up to 24.\nEquip: Melee attacks and harmful spells have a chance to increase spell damage by up to 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446189] = { ["name"] = "Shoulderpads of Obsession", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Essence of Water , Rugged Leather (12)\nShoulderpads of Obsession\nBinds when picked up\nShoulder Leather\n129 Armor\n+12 Intellect\n+16 Spirit\nDurability 70 / 70\n50\nRequires Leatherworking\n(250)\nEquip: Increases healing done by spells and effects by up to 29.\nEquip: Healing spells have a chance to increase your healing by up to 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446190] = { ["name"] = "Wailing Chain Mantle", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Green Dragonscale (8), Rugged Leather (8)\nWailing Chain Mantle\nBinds when picked up\nShoulder Mail\n268 Armor\n+10 Stamina\n+11 Intellect\nDurability 85 / 85\n50\nRequires Leatherworking\n(250)\nEquip: Increases healing done by spells and effects by up to 31.\nEquip: Restores 4 mana per 5 sec.\nEquip: Healing spells have a chance to increase your healing by up to 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446191] = { ["name"] = "Baleful Pauldrons", ["text"] = "45 sec cast\nTools: Blacksmith Hammer\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares\nBaleful Pauldrons\nBinds when picked up\nShoulder Plate\n472 Armor\n+10 Stamina\n+13 Intellect\nDurability 100 / 100\n50\nRequires Blacksmithing\n(250)\nEquip: Increases healing done by spells and effects by up to 31.\nEquip: Restores 2 mana per 5 sec.\nEquip: Healing spells have a chance to increase your healing by up to 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446192] = { ["name"] = "Membrane of Dark Neurosis", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Cured Rugged Hide (2), Rugged Leather (6)\nMembrane of Dark Neurosis\nBinds when picked up\nShoulder Leather\n129 Armor\n+14 Intellect\nDurability 70 / 70\n50\nRequires Leatherworking\n(250)\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 20.\nEquip: Melee attacks and harmful spells have a chance to increase spell damage by up to 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446193] = { ["name"] = "Fractured Mind Pauldrons", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Felcloth (8), Bolt of Runecloth (8)\nFractured Mind Pauldrons\nBinds when picked up\nShoulder Cloth\n64 Armor\n+14 Intellect\n+12 Spirit\nDurability 60 / 60\n50\nRequires Tailoring\n(250)\nEquip: Increases damage and healing done by magical spells and effects by up to 18.\nEquip: Damaging spells have a chance to increase your spell casting speed by 10% for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446194] = { ["name"] = "Mantle of Insanity", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Living Essence (4), Bolt of Runecloth (10)\nMantle of Insanity\nBinds when picked up\nShoulder Cloth\n64 Armor\n+12 Stamina\n+13 Intellect\n+12 Spirit\nDurability 60 / 60\n50\nRequires Tailoring\n(250)\nEquip: Increases healing done by spells and effects by up to 20.\nEquip: Healing spells have a chance to increase your healing by up to 50 for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
entries[446195] = { ["name"] = "Shoulderpads of the Deranged", ["text"] = "45 sec cast\nReagents:\nNightmare Seed (10), Inert Mantle of Nightmares , Felcloth (6), Essence of Water , Bolt of Runecloth (3)\nShoulderpads of the Deranged\nBinds when picked up\nShoulder Cloth\n104 Armor\n+15 Stamina\n+13 Intellect\nDurability 60 / 60\n50\nRequires Tailoring\n(250)\nEquip: Increases damage and healing done by magical spells and effects by up to 13.\nEquip: Damaging spells have a chance to increase your spell damage by 30 and chance to dodge by 2% for 10 sec. This has no effect outside of areas under the influence of the Nightmare. (Proc chance: 30%, 40s cooldown)" }
